def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    # Determine unit based on magnitude
    if n < 1_000_000:
        unit = "mil"
    elif n < 1_000_000_000:
        unit = "mi"
    else:
        unit = "bi"

    factor = {
        "mil": 1000,
        "mi": 1_000_000,
        "bi": 1_000_000_000
    }[unit]

    # Compute value to round: n / factor
    raw_val = n / factor

    # Round half up to one decimal place using Decimal for correct rounding
    from decimal import Decimal, ROUND_HALF_UP
    rounded_val = float(Decimal(str(raw_val)).quantize(Decimal('0.1'), rounding=ROUND_HALF_UP))

    # Format with one decimal and comma as decimal separator; drop trailing ",0"
    formatted = f"{rounded_val:.1f}".replace('.', ',')
    if formatted.endswith(",0"):
        formatted = formatted[:-2]  # remove trailing ",0"

    return f"{formatted} {unit}"
