def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all nodes (keys and values)
    nodes = set()
    for item in deps:
        nodes.add(item)
        for dep in deps[item]:
            nodes.add(dep)

    # Initialize adjacency list and indegree counts
    adj = {node: [] for node in nodes}
    indeg = {node: 0 for node in nodes}

    for item, dep_list in deps.items():
        for dep in dep_list:
            adj[dep].append(item)   # edge from dependency -> dependent
            indeg[item] += 1

    import heapq
    heap = [node for node in nodes if indeg[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            indeg[neighbor] -= 1
            if indeg[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")
    return result
