def wrap(text: str, width: int) -> list[str]:
    if not text or width <= 0:
        return []

    # Split the input into words using any whitespace as delimiter.
    # This automatically discards leading/trailing whitespace and collapses multiple spaces.
    words = text.split()

    lines = []          # result list of strings (lines)
    current_line = ""   # build the line being constructed

    for word in words:
        if len(word) <= width:
            # The whole word fits on the current line; add it with a space separator
            if current_line == "":
                current_line = word
            else:
                current_line += " " + word
        else:
            # Word is longer than width: break it into chunks of size `width`.
            for i in range(0, len(word), width):
                chunk = word[i:i+width]
                if current_line == "":
                    current_line = chunk
                else:
                    # Add a space before the chunk (since we are continuing the same line)
                    current_line += " " + chunk

    # If there is any remaining content in `current_line`, add it as the last line.
    if current_line != "":
        lines.append(current_line)

    return lines
