def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all unique nodes (keys and values)
    nodes = set()
    for item in deps:
        nodes.add(item)  # the key itself is an item
        for dep in deps[item]:
            nodes.add(dep)  # dependencies may not be keys

    # Initialize indegree for each node: number of incoming edges (i.e., how many dependencies it has)
    indegree = {node: 0 for node in nodes}

    # Build adjacency list: edge from dependency -> dependent
    adj = {node: [] for node in nodes}
    for item, dep_list in deps.items():
        for dep in dep_list:
            # edge from dep to item (dep must come before item)
            adj[dep].append(item)
            indegree[item] += 1  # increment indegree of the dependent

    # Priority queue (min-heap) for nodes with zero indegree, picking alphabetically smallest first
    import heapq
    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for neighbor in adj.get(node, []):
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(order) != len(nodes):
        raise ValueError("Cycle detected in dependencies")

    return order
