import re

def wrap(text: str, width: int) -> list[str]:
    if not text or width <= 0:
        return []

    # Extract words (sequences of non-whitespace characters)
    words = re.findall(r'\S+', text)

    lines = []          # result lines
    current_line = ""   # buffer for the line we are building

    for word in words:
        if len(word) <= width:
            # Whole word fits; add it to current line with a space separator
            if current_line == "":
                # start new line
                current_line = word
            else:
                # there is already content on the line, add a space then the word
                current_line += " " + word
        else:
            # Word longer than width: split into chunks of at most `width` characters
            chunk_size = width
            for i in range(0, len(word), chunk_size):
                chunk = word[i:i+chunk_size]
                if current_line == "":
                    # start a new line with this chunk (no preceding space)
                    current_line = chunk
                else:
                    # add a space before the chunk and then the chunk
                    current_line += " " + chunk

    # If there is any leftover content in current_line, add it as the last line
    if current_line != "":
        lines.append(current_line)

    return lines
