def deep_merge(base: dict, override: dict) -> dict:
    result = {}
    # Union of keys from both dictionaries
    for key in set(base.keys()) | set(override.keys()):
        b_val = base.get(key)
        o_val = override.get(key)

        # If the override value is explicitly None, delete the key
        if o_val is None:
            continue

        # Both values are dicts -> merge recursively
        if isinstance(b_val, dict) and isinstance(o_val, dict):
            result[key] = deep_merge(b_val, o_val)
        else:
            # Override wins for non-dict values (including lists, etc.)
            result[key] = o_val
    return result
