from datetime import datetime

def latest_by_key(records: list[dict], key: str) -> list[dict]:
    # Helper to parse ISO 8601 strings, handling trailing 'Z'
    def parse_iso(s: str):
        if s.endswith('Z'):
            s = s[:-1] + '+00:00'
        return datetime.fromisoformat(s)

    # Store for each distinct value of `key`: (best_record, best_dt, best_index)
    latest_for_value = {}

    for idx, rec in enumerate(records):
        val = rec.get(key)  # may be None if key missing
        upd_str = rec.get('updated_at')
        dt = parse_iso(upd_str) if upd_str is not None else None

        entry = latest_for_value.get(val)
        if entry is None:
            latest_for_value[val] = (rec, dt, idx)
        else:
            best_rec, best_dt, best_idx = entry
            # Prefer later index on tie, or more recent datetime
            if dt > best_dt or (dt == best_dt and idx > best_idx):
                latest_for_value[val] = (rec, dt, idx)

    # Preserve order of first appearance of each distinct value
    seen = set()
    unique_values = []
    for rec in records:
        val = rec.get(key)
        if val not in seen:
            seen.add(val)
            unique_values.append(val)

    result = [latest_for_value[val][0] for val in unique_values]
    return result
